import{_ as t,o,c as n,ah as s}from"./chunks/framework.e_ysbW9u.js";const a="/projects/ROSPug/en/latest/assets/image2.BWPTgHm5.png",i="/projects/ROSPug/en/latest/assets/image3.BUA6UjaN.png",r="/projects/ROSPug/en/latest/assets/image4.DVvYjABn.png",c="/projects/ROSPug/en/latest/assets/image5.Bb8xpL_M.png",l="/projects/ROSPug/en/latest/assets/image6.DpItdnI_.png",h="/projects/ROSPug/en/latest/assets/image7.CI7xrZGR.png",g="/projects/ROSPug/en/latest/assets/image8.2LmN0LAN.png",p="/projects/ROSPug/en/latest/assets/image9.CUiVosi7.png",d="/projects/ROSPug/en/latest/assets/image10.BVMhTyba.png",m="/projects/ROSPug/en/latest/assets/image11.DS3blUKh.png",u="/projects/ROSPug/en/latest/assets/image12.BgdvDQ-q.png",_="/projects/ROSPug/en/latest/assets/image13.wjxJIodg.png",b="/projects/ROSPug/en/latest/assets/image14.DVEH25gl.png",f="/projects/ROSPug/en/latest/assets/image15.CQ0hjE9-.png",y="/projects/ROSPug/en/latest/assets/image16.ZqN-767C.png",q="/projects/ROSPug/en/latest/assets/image17.BaaXdQQQ.png",T=JSON.parse('{"title":"3. Remote Connection Tool Installation & Connection","description":"","frontmatter":{},"headers":[],"relativePath":"docs/3.Remote_Connection_Tool_Installation_Connection.md","filePath":"docs/3.Remote_Connection_Tool_Installation_Connection.md"}'),w={name:"docs/3.Remote_Connection_Tool_Installation_Connection.md"};function P(k,e,C,R,v,S){return o(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="_3-remote-connection-tool-installation-connection" tabindex="-1">3. Remote Connection Tool Installation &amp; Connection <a class="header-anchor" href="#_3-remote-connection-tool-installation-connection" aria-label="Permalink to &quot;3. Remote Connection Tool Installation &amp; Connection&quot;">​</a></h1><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Before running the robot game, checking, and revising the code, you need to install and connect the remote connection tool.</p></section><h2 id="_3-1-preparation" tabindex="-1">3.1 Preparation <a class="header-anchor" href="#_3-1-preparation" aria-label="Permalink to &quot;3.1 Preparation&quot;">​</a></h2><h3 id="_3-1-1-hardware-preparation" tabindex="-1">3.1.1 Hardware Preparation <a class="header-anchor" href="#_3-1-1-hardware-preparation" aria-label="Permalink to &quot;3.1.1 Hardware Preparation&quot;">​</a></h3><p>Get ready with a laptop; if you&#39;re using a desktop, make sure to have a wireless network card that supports the 5G frequency band, or you may face issues locating the ROSPug hotspot.</p><h3 id="_3-1-2-nomachine-installation" tabindex="-1">3.1.2 NoMachine Installation <a class="header-anchor" href="#_3-1-2-nomachine-installation" aria-label="Permalink to &quot;3.1.2 NoMachine Installation&quot;">​</a></h3><p>(1) Open the software pack <a href="./Appendix.html">nomachine_7.1.3_1.exe</a> in the same folder.</p><p>(2) Click <strong>&quot;Next&quot;</strong> button.</p><img loading="lazy" height="385" width="497" src="'+a+'" class="common_img"><p>(3) Set the language as <strong>&quot;English&quot;</strong> and tick <strong>&quot;I accept the agreement&quot;</strong>. Then move to <strong>&quot;Next&quot;</strong> step.</p><img loading="lazy" height="385" width="497" src="'+i+'" class="common_img"><p>(4) Remain the default storage path for NoMachine, then click <strong>&quot;Next&quot;</strong>.</p><img loading="lazy" height="385" width="497" src="'+r+'" class="common_img"><p>(5) Please wait until the installation completes. Click <strong>&quot;Finish&quot;</strong> button.</p><img loading="lazy" height="385" width="497" src="'+c+'" class="common_img"><p>(6) Click <strong>&quot;Yes&quot;</strong> to restart the computer. Please don&#39;t skip this step!</p><img loading="lazy" height="213" width="459" src="'+l+'" class="common_img"><h2 id="_3-2-access-under-ap-direct-connection-sta-lan-mode" tabindex="-1">3.2 Access under AP Direct Connection/ STA LAN Mode <a class="header-anchor" href="#_3-2-access-under-ap-direct-connection-sta-lan-mode" aria-label="Permalink to &quot;3.2 Access under AP Direct Connection/ STA LAN Mode&quot;">​</a></h2><p>(1) ROSPug is default to AP direct connection mode. After it boots up successfully, it will create a WiFi starting with <strong>&#39;HW&#39;</strong>. Connect your computer to this WiFi.Password: <strong>hiwonder</strong></p><img loading="lazy" height="105" width="360" src="'+h+'" class="common_img"><p>(2) Open NoMachine. Input <strong>&quot;192.168.149.1&quot;</strong> in the search bar, then click-on <strong>&quot;Configure connection to new host 192.168.149.1&quot;</strong>.</p><img loading="lazy" height="154" width="843" src="'+g+'" class="common_img"><p>(3) Rename it to <strong>&#39;ROSPug&#39;</strong> and leave the remaining settings unchanged. Then, click <strong>&#39;Connect&#39;</strong>.</p><img loading="lazy" height="557" width="848" src="'+p+'" class="common_img"><p>(4) Use the username <strong>&quot;hiwonder&quot;</strong> and password <strong>&quot;hiwonder&quot;</strong> to log in. Remember to select <strong>&quot;Save this password in the connection file&quot;</strong> before clicking the <strong>&quot;Login&quot;</strong> button to access the Jetson Nano desktop.</p><img loading="lazy" height="607" width="897" src="'+d+'" class="common_img"><img loading="lazy" height="575" width="895" src="'+m+'" class="common_img"><img loading="lazy" height="575" width="895" src="'+u+'" class="common_img"><img loading="lazy" height="575" width="895" src="'+_+'" class="common_img"><img loading="lazy" height="594" width="1000" src="'+b+'" class="common_img"><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>If the robot is configured to STA LAN mode, the instructions are the same as before. However, in step 2, 3, and 4, you need to use the corresponding IP address, username, and password for the STA LAN mode configuration.</p></section><h2 id="_3-3-method-to-fix-abnormal-resolution" tabindex="-1">3.3 Method To Fix Abnormal Resolution <a class="header-anchor" href="#_3-3-method-to-fix-abnormal-resolution" aria-label="Permalink to &quot;3.3 Method To Fix Abnormal Resolution&quot;">​</a></h2><p>When using the remote tool NoMachine to connect to the ROSPug, if you experience abnormal screen resolution (as shown in the figure below), you can address this issue by following the methods outlined in 3.3.1 or 3.3.2 (beginners are advised to use the approach detailed in 3.3.1).</p><img loading="lazy" height="344" width="380" src="'+f+'" class="common_img"><h3 id="_3-3-1-change-resolution-on-the-desktop" tabindex="-1">3.3.1 Change Resolution On The Desktop <a class="header-anchor" href="#_3-3-1-change-resolution-on-the-desktop" aria-label="Permalink to &quot;3.3.1 Change Resolution On The Desktop&quot;">​</a></h3><p>(1) Double-click <strong>&quot;1920*1080&quot;</strong> icon to change the resolution.</p><img loading="lazy" height="344" width="380" src="'+y+'" class="common_img"><p>(2) After revision, you can directly close the window.</p><img loading="lazy" height="631" width="1063" src="'+q+'" class="common_img"><p>(3) Lastly, restart NoMachine.</p><h3 id="_3-3-2-change-resolution-using-command" tabindex="-1">3.3.2 Change Resolution Using Command <a class="header-anchor" href="#_3-3-2-change-resolution-using-command" aria-label="Permalink to &quot;3.3.2 Change Resolution Using Command&quot;">​</a></h3><p>(1) Double-click the terminal icon to open the command line terminal.</p><p>(2) Type and press Enter to delete the command history file.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>rm -rf ~/.bash_history</span></span></code></pre></div><p>(3) Type and press Enter to clear the command history. If you see the message <strong>&#39;History file deleted.&#39;</strong>, the process was successful.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>history -c</span></span></code></pre></div><p>(4) Type and press Enter to adjust the screen resolution.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>xrandr --fb 1920x1080</span></span></code></pre></div><p>(5) Once these changes are made, click the close button in the upper-right corner to close the current window.</p><p>(6) Reopen NoMachine to apply the changes.</p>',50)])])}const O=t(w,[["render",P]]);export{T as __pageData,O as default};
